-- Massa de teste MySQL: 50 comandos INSERT individuais por tabela.
-- Tabelas: usuarios, projetos, manutencoes e anexo.
-- Execute uma unica vez em uma base vazia criada pelo DDL do exercicio 1.
-- Hash ficticio: nao use estas contas para autenticar em producao.

USE API2;

-- 50 usuarios de apoio, incluindo o responsavel de suporte de ID 2.

-- 50 projetos; responsaveis e vendedores referenciam usuarios existentes.

-- 50 manutencoes; cada uma referencia seu projeto correspondente.
-- O status persistido segue o ENUM MySQL do DDL do projeto.

-- 50 anexos, um para cada manutencao. O tamanho em bytes usa OCTET_LENGTH do MySQL.

-- Resultado esperado: 50 linhas em cada uma das quatro tabelas.
SELECT 'usuarios' AS tabela, COUNT(*) AS linhas FROM usuarios
UNION ALL SELECT 'projetos', COUNT(*) FROM projetos
UNION ALL SELECT 'manutencoes', COUNT(*) FROM manutencoes
UNION ALL SELECT 'anexo', COUNT(*) FROM anexo;
